// Router value index — record JAH-GPC-WIFI7ROUTER-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"speed_mbps": 19000, "streams": 16, "price_usd": 600};
var value = (m.speed_mbps*m.streams/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-WIFI7ROUTER-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-WIFI7ROUTER-000001|' + value.toFixed(2) + ' router index');

